from pathlib import Path
p=Path('index.html');old=p.read_text(encoding='utf-8');dialogs=old[old.index('<dialog id="help-dialog"'):old.index('<footer>')]
html='''<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#211c25"><meta name="description" content="Three Vikings. Six arcade worlds. Leave no Viking behind."><title>Last Call — A Viking Puzzle Adventure</title><link rel="stylesheet" href="style.css?v=hud25"></head>
<body><main><section class="game-shell" aria-label="Last Call game">
<div class="game-top"><button id="rounds" title="Choose a round">1/6 · THE NEON STAG</button><div class="toolbar-tools"><span id="timer">00:00</span><button id="zoom" aria-label="Toggle 1x overview and 2x exploration zoom" title="Zoom · V">2×</button><button id="sound" aria-label="Toggle game sound" title="Sound">♪<span class="sr-only">SOUND OFF</span></button><button id="debug" aria-label="Open debug panel" title="Debug · F2">DBG</button><button id="fullscreen" aria-label="Enter fullscreen" title="Fullscreen">⛶</button><button id="pause" aria-label="Pause game" title="Pause · Esc">Ⅱ</button><button id="restart" aria-label="Restart level" title="Restart · R">↻</button><button id="help" aria-label="How to play" title="How to play">?</button></div></div>
<div class="below"><div class="crew">'''
for i,name in enumerate(['ERIK','BALEOG','OLAF']):
 html+=f'''<button class="hero-card{' active' if i==0 else ''}" data-hero="{i}" aria-label="Select {name.title()}"><canvas width="64" height="64" id="portrait{i}"></canvas><div><span class="hero-name"><kbd>{i+1}</kbd>{name}</span><span class="hud-health" aria-label="3 health"><i></i><i></i><i></i></span></div></button>'''
html+='''</div><div class="key-guide"><span>← → MOVE</span><span>SPACE ACTION</span><span>D ALT</span><span>E USE</span></div></div>
<div class="viewport"><canvas id="game" width="1440" height="650" tabindex="0" aria-label="Puzzle platformer. Arrow keys to move, Space/F primary action, D alternate action, E/S use, 1 2 3 to switch heroes."></canvas><div class="start-overlay" id="start"><div class="ticket"><span class="eyebrow">THREE VIKINGS · SIX WORLDS</span><h1>LAST<br><span>CALL</span></h1><p>Trapped after closing time.<br>Escape the pub. Survive the arcade.<br>Leave no Viking behind.</p><button id="play">START GAME <span>▶</span></button><small>ARROWS + ACTION · OR TOUCH CONTROLS</small></div></div><div id="win" class="win" hidden><span class="eyebrow">LEVEL COMPLETE</span><h2>Skål! You made it.</h2><p>Three heroes. One excellent escape.</p><button id="next-round">ENTER NEXT GAME →</button><button id="again">ONE MORE ROUND ↻</button></div></div>
<div class="game-bottom"><span class="message-icon" aria-hidden="true">ᛉ</span><div class="message-copy"><span id="message-label">QUEST</span><span id="mission">Restore the power. Bring everyone to the exit.</span><div id="toast" class="toast" role="status" aria-live="polite"></div></div><button id="hint" aria-label="Show puzzle hint">HINT <span>?</span></button></div>
</section><div class="mobile-controls" aria-label="Touch controls"><div class="movement-pad"><button aria-label="Move left" data-key="left">◀</button><button aria-label="Move right" data-key="right">▶</button></div><div class="action-pad"><button data-key="interact">USE<small>E / S</small></button><button data-key="secondary">ALT<small>BASH · D</small></button><button data-key="primary">ACTION<small>JUMP · SPACE/F</small></button></div></div>
'''+dialogs+'''</main><script type="module" src="game.js?v=hud25"></script></body></html>'''
p.write_text(html,encoding='utf-8')
for p in Path('.').glob('*.js'):
 s=p.read_text(encoding='utf-8-sig').replace('collision24','hud25');p.write_text(s,encoding='utf-8')
p=Path('game.js');s=p.read_text(encoding='utf-8');s=s.replace("document.querySelector('#toast').classList.add('show');", "document.querySelector('#toast').classList.add('show');document.querySelector('#message-label').textContent='MESSAGE';")
s=s.replace("if(now>toastUntil)document.querySelector('#toast').classList.remove('show');", "if(now>toastUntil){document.querySelector('#toast').classList.remove('show');document.querySelector('#message-label').textContent='QUEST';}document.querySelectorAll('.hero-card').forEach((el,i)=>{el.querySelector('.hud-health').setAttribute('aria-label',s.heroes[i].hp+' health');el.querySelectorAll('.hud-health i').forEach((pip,n)=>pip.classList.toggle('spent',n>=s.heroes[i].hp));});")
p.write_text(s,encoding='utf-8')
